source('scripts/load.R');cfg<-jsonlite::read_json('config/study.json',simplifyVector=TRUE)
d<-read.csv('results/replicate_metrics.csv');checks<-list()
check<-function(name,value){checks[[name]]<<-isTRUE(value);if(!isTRUE(value))stop('Audit failed: ',name)}
check('2400_unique_evaluations',nrow(d)==2400&&!anyDuplicated(d[,c('replicate','scenario','threshold','method')]))
check('100_replicates_in_each_cell',all(table(d$scenario,d$threshold,d$method)==100))
check('198_true_pairs_per_population',all(d$true_pairs==198&d$TP+d$FN==198))
check('precision_independently_recomputed',all(abs(d$precision-d$TP/(d$TP+d$FP))<1e-12|is.na(d$precision)))
check('all_population_sensitivity_recomputed',max(abs(d$sensitivity_all-d$TP/198))<1e-12)
check('sampled_sensitivity_recomputed',max(abs(d$sensitivity_sampled-d$TP/d$sampled_true_pairs),na.rm=TRUE)<1e-12)
check('FPR_recomputed',max(abs(d$false_positive_rate-d$FP/(choose(150,2)-198)))<1e-12)
check('QC_denominators_valid',all(d$qc_eligible_pairs<=d$available_pairs&d$available_pairs<=choose(150,2)))
s<-read.csv('results/performance_summary.csv');manual<-do.call(rbind,lapply(c('precision','sensitivity_all','sensitivity_sampled','false_positive_rate'),function(metric){z<-mc(d,c('scenario','threshold','method'),metric);z$metric<-metric;z}));z<-merge(s,manual,by=c('scenario','threshold','method','metric'));check('all_MC_means_and_intervals_recomputed',nrow(z)==96&&max(abs(z$mean.x-z$mean.y),abs(z$lower.x-z$lower.y),abs(z$upper.x-z$upper.y),na.rm=TRUE)<1e-10)
p<-readRDS('results/simulation.rds')$example;m<-read.csv('data/synthetic_isolates.csv')
check('only_synthetic_ids',nrow(m)==150&&all(grepl('^SIM[0-9]{3}$',m$isolate)))
check('150_tip_tree_matches_metadata',setequal(ape::read.tree('results/full_synthetic_tree.nwk')$tip.label,m$isolate))
check('36_tip_display_subset',length(ape::read.tree('results/display_synthetic_tree.nwk')$tip.label)==36)
check('sequence_truth_recomputed',all(vapply(1:10,function(i)sum(p$sequences[i,]!=p$sequences[i+1,])==p$distance[i,i+1],logical(1))))
readme<-paste(readLines('README.md',warn=FALSE),collapse='\n');figs<-regmatches(readme,gregexpr('figures/[a-z_]+[.]png',readme))[[1]]
check('README_figures_present',length(figs)>=7&&all(file.exists(figs)))
jsonlite::write_json(list(passed=TRUE,checks=checks,check_count=length(checks),scope='Committed R simulation metrics; separate Nextflow execution audit in results/wgs/wgs_validation.json'),'provenance/R_validation.json',pretty=TRUE,auto_unbox=TRUE)
cat(length(checks),'R release audit checks passed.\n')
